CREATE TABLE site (site text PRIMARY KEY, site_region text NOT NULL);
CREATE TABLE sensor (sensor text PRIMARY KEY, site text NOT NULL REFERENCES site);
CREATE TABLE reading (sensor text REFERENCES sensor, ts int, value int, PRIMARY KEY (sensor, ts));
INSERT INTO site SELECT DISTINCT site, site_region FROM reading_flat;
INSERT INTO sensor SELECT DISTINCT sensor, site FROM reading_flat;
INSERT INTO reading SELECT sensor, ts, value FROM reading_flat;

SELECT
  (SELECT COUNT(*) FROM (
     SELECT sensor, site, site_region, ts, value FROM reading_flat
     EXCEPT
     SELECT r.sensor, s.site, t.site_region, r.ts, r.value
     FROM reading r JOIN sensor s ON s.sensor = r.sensor JOIN site t ON t.site = s.site) a) AS lost_rows,
  (SELECT COUNT(*) FROM (
     SELECT r.sensor, s.site, t.site_region, r.ts, r.value
     FROM reading r JOIN sensor s ON s.sensor = r.sensor JOIN site t ON t.site = s.site
     EXCEPT
     SELECT sensor, site, site_region, ts, value FROM reading_flat) b) AS invented_rows;

